const f = require('../functions');

exports.protocol = 'GT06+';
exports.model_name = 'GT06+ Enhanced';
exports.compatible_hardware = ['GT06N', 'GT06', 'GT06E', 'GT06F', 'GT06H', 'TK103', 'TK303', 'UM552'];

var adapter = function (device) {
  if (!(this instanceof adapter)) {
    return new adapter(device);
  }

  this.format = {'start': '(', 'end': ')', 'separator': ''};
  this.device = device;
  this.__count = 1;

  /*******************************************
   ENHANCED PARSER WITH ANALYSIS
   *******************************************/
  this.parse_data = function (data) {
    try {
      var hexData = this.bufferToHexString(data);
      console.log('Raw hex data received:', hexData);
      
      if (hexData.length < 10) {
        return { 
          cmd: 'noop', 
          action: 'noop', 
          device_id: '',
          analysis: this.createSimpleAnalysis(hexData, 'unknown', null) // Always include analysis
        };
      }

      var parts = {
        'raw': hexData,
        'raw_buffer': data,
        'start': hexData.substr(0, 4)
      };

      if (parts['start'] !== '7878' && parts['start'] !== '7979') {
        return { 
          cmd: 'noop', 
          action: 'noop', 
          device_id: '',
          analysis: this.createSimpleAnalysis(hexData, 'unknown', null)
        };
      }

      // Parse basic structure
      parts['length'] = parseInt(hexData.substr(4, 2), 16);
      parts['protocol_id'] = hexData.substr(6, 2).toLowerCase();
      console.log('Protocol ID:', parts['protocol_id']);
      
      // Extract data section
      const dataStart = 8;
      parts['data'] = hexData.substring(dataStart, dataStart + (parts['length'] - 1) * 2);
      parts['data_body'] = parts['data']; // For backward compatibility
      
      // Get device ID - ENHANCED EXTRACTION
      let deviceId = null;
      let extractedIMEI = null;
      
      // For login packets (protocol 01)
      if (parts['protocol_id'] === '01') {
        extractedIMEI = this.extractIMEIEnhanced(hexData);
        parts['device_id'] = extractedIMEI;
        console.log(`Login packet, extracted IMEI: ${extractedIMEI}`);
      } else {
        // For other packets, get from device object
        deviceId = this.device.getUID ? this.device.getUID() : null;
        parts['device_id'] = deviceId;
        extractedIMEI = deviceId;
      }
      
      // Create COMPREHENSIVE analysis - ALWAYS attach it
      parts['analysis'] = this.createComprehensiveAnalysis(hexData, parts['protocol_id'], extractedIMEI);
      
      console.log(`Analysis attached - Brands: ${parts['analysis'].brands.join(', ')}, PacketType: ${parts['analysis'].packetType}`);
      
      // Map protocol to action
      this.map_gt06_protocol(parts);

      console.log(`Parsed: Protocol=${parts['protocol_id']}, Action=${parts.action}, DeviceID=${parts['device_id'] || 'none'}`);
      return parts;
    } catch (error) {
      console.error('Error parsing data:', error);
      return { 
        cmd: 'noop', 
        action: 'noop', 
        device_id: '',
        analysis: this.createSimpleAnalysis('', 'error', null)
      };
    }
  };

  // ENHANCED IMEI extraction for GT06 protocol
  this.extractIMEIEnhanced = function(hexData) {
    try {
      // GT06 login packet structure: 7878 0D 01 [IMEI 8 bytes] [Serial 2 bytes] [CRC 2 bytes] 0D0A
      if (hexData.length < 28) return null; // Minimum length check
      
      const protocolNumber = hexData.substr(6, 2);
      if (protocolNumber !== '01') return null; // Only login packets have IMEI
      
      // IMEI is at position 8-23 (8 bytes = 16 hex chars)
      const imeiHex = hexData.substring(8, 24);
      console.log(`IMEI Hex: ${imeiHex}, Length: ${imeiHex.length}`);
      
      if (imeiHex.length !== 16) return null;
      
      // Convert hex to decimal IMEI (BCD format)
      let imei = '';
      for (let i = 0; i < imeiHex.length; i += 2) {
        const byteHex = imeiHex.substring(i, i + 2);
        const byteValue = parseInt(byteHex, 16);
        
        // Extract two BCD digits from each byte
        const digit1 = Math.floor(byteValue / 16);
        const digit2 = byteValue % 16;
        
        // Skip if digit is 0xF (padding) for the last byte
        if (digit1 !== 0xF) imei += digit1.toString();
        if (digit2 !== 0xF) imei += digit2.toString();
      }
      
      // IMEI should be 15 digits
      imei = imei.substring(0, 15);
      console.log(`Extracted IMEI: ${imei}`);
      
      return imei;
    } catch (error) {
      console.error('Error extracting IMEI:', error);
      return null;
    }
  };

  // COMPREHENSIVE analysis creation
  this.createComprehensiveAnalysis = function(hexData, protocolId, deviceId) {
    const analysis = {
      timestamp: new Date().toISOString(),
      deviceId: deviceId,
      isGT06: true,
      protocolNumber: protocolId,
      packetType: 'Unknown',
      brands: [],
      protocols: ['GT06'],
      features: {},
      rawPreview: hexData.substring(0, 50)
    };

    try {
      // Set packet type based on protocol
      const protocolMap = {
        '01': 'Login',
        '10': 'GPS Data',
        '11': 'GPS Data',
        '12': 'Location Data',
        '13': 'Heartbeat/Status',
        '16': 'Alarm',
        '17': 'LBS Location',
        '1a': 'Address Query',
        '22': 'GPS + Address',
        '26': 'Alarm + Address'
      };
      
      analysis.packetType = protocolMap[protocolId] || `Unknown Protocol (0x${protocolId})`;
      
      // Enhanced brand detection with more prefixes
      if (deviceId) {
        const cleanDeviceId = deviceId.toString();
        
        // Teltonika (most common in your logs)
        if (cleanDeviceId.startsWith('086872') || cleanDeviceId.startsWith('86872')) {
          analysis.brands.push('Teltonika');
          analysis.brands.push('GT06 Family');
          analysis.family = 'Teltonika';
          analysis.features.crsTerminal = true;
        }
        // Queclink
        else if (cleanDeviceId.startsWith('035865') || cleanDeviceId.startsWith('35865')) {
          analysis.brands.push('Queclink');
          analysis.brands.push('GT06 Family');
          analysis.family = 'Queclink';
          analysis.features.crsTerminal = true;
        }
        // Suntech
        else if (cleanDeviceId.startsWith('086494') || cleanDeviceId.startsWith('86494')) {
          analysis.brands.push('Suntech');
          analysis.brands.push('GT06 Family');
          analysis.family = 'Suntech';
          analysis.features.crsTerminal = true;
        }
        // Concox
        else if (cleanDeviceId.startsWith('086108') || cleanDeviceId.startsWith('86108')) {
          analysis.brands.push('Concox');
          analysis.brands.push('GT06 Family');
          analysis.family = 'Concox';
        }
        // Meitrack
        else if (cleanDeviceId.startsWith('086219') || cleanDeviceId.startsWith('86219')) {
          analysis.brands.push('Meitrack');
          analysis.brands.push('GT06 Family');
          analysis.family = 'Meitrack';
        }
        // Generic GT06 devices
        else if (cleanDeviceId.length === 15) {
          // Check IMEI TAC (Type Allocation Code) for brand detection
          const tac = cleanDeviceId.substring(0, 8);
          analysis.brands.push('GT06 Family');
          
          // Common TAC prefixes (you can expand this list)
          if (['86872006', '35865710'].includes(tac.substring(0, 8))) {
            analysis.brands.push('Teltonika/Queclink Variant');
          }
        }
        
        // Remove duplicates
        analysis.brands = [...new Set(analysis.brands)];
        
        // Default if no brand detected
        if (analysis.brands.length === 0) {
          analysis.brands.push('GT06 Compatible');
        }
      }
      
      // Protocol-specific features
      if (protocolId === '12' || protocolId === '22') {
        analysis.features.hasGPS = true;
        analysis.features.hasSpeed = true;
      }
      if (protocolId === '13') {
        analysis.features.heartbeat = true;
      }
      if (protocolId === '16' || protocolId === '26') {
        analysis.features.alarm = true;
      }
      
    } catch (error) {
      console.error('Error in createComprehensiveAnalysis:', error);
    }

    return analysis;
  };

  // Simple analysis fallback
  this.createSimpleAnalysis = function(hexData, protocolId, deviceId) {
    return {
      timestamp: new Date().toISOString(),
      deviceId: deviceId,
      isGT06: hexData.startsWith('7878') || hexData.startsWith('7979'),
      protocolNumber: protocolId,
      packetType: 'Unknown',
      brands: ['GT06 Family'],
      protocols: ['GT06']
    };
  };

  // Rest of the file remains the same...
  this.map_gt06_protocol = function(parts) {
    const protocolMap = {
      '01': { cmd: 'login_request', action: 'login_request' },
      '10': { cmd: 'ping', action: 'ping' },
      '11': { cmd: 'ping', action: 'ping' },
      '12': { cmd: 'ping', action: 'ping' },
      '13': { cmd: 'heartbeat', action: 'heartbeat' },
      '16': { cmd: 'alarm', action: 'alarm' },
      '17': { cmd: 'lbs_location', action: 'lbs_location' },
      '18': { cmd: 'status', action: 'status' },
      '19': { cmd: 'status', action: 'status' },
      '1a': { cmd: 'alarm', action: 'alarm' },
      '1b': { cmd: 'alarm', action: 'alarm' },
      '1c': { cmd: 'alarm', action: 'alarm' },
      '22': { cmd: 'ping', action: 'ping' },
      '26': { cmd: 'alarm', action: 'alarm' },
      '27': { cmd: 'alarm', action: 'alarm' },
      '28': { cmd: 'ping', action: 'ping' },
      '2a': { cmd: 'alarm', action: 'alarm' },
      '2b': { cmd: 'alarm', action: 'alarm' },
      '2c': { cmd: 'alarm', action: 'alarm' }
    };

    const mapping = protocolMap[parts['protocol_id']] || { cmd: 'noop', action: 'noop' };
    parts.cmd = mapping.cmd;
    parts.action = mapping.action;
  };

  this.bufferToHexString = function (buffer) {
    var str = '';
    for (var i = 0; i < buffer.length; i++) {
      var hex = buffer[i].toString(16);
      str += hex.length === 1 ? '0' + hex : hex;
    }
    return str;
  };

  this.authorize = function () {
    var response = '787805010001D9DC0D0A';
    console.log('Sending login response:', response);
    this.device.send(Buffer.from(response, 'hex'));
  };
  
  this.receive_heartbeat = function (msg_parts) {
    var response = '787805130001D9DC0D0A';
    console.log('Sending heartbeat response:', response);
    this.device.send(Buffer.from(response, 'hex'));
  };

  // GPS parsing methods (keep your existing)
  this.get_ping_data = function (msg_parts) {
    try {
      var str = msg_parts.data_body || msg_parts.data;
      console.log('Parsing location data, length:', str.length);
      
      if (str.length >= 38) {
        return this.parse_standard_gps_data(str, msg_parts);
      } else if (str.length >= 20) {
        return this.parse_compact_gps_data(str, msg_parts);
      } else {
        console.error('GPS data too short:', str.length);
        return false;
      }
    } catch (error) {
      console.error('Error parsing ping data:', error);
      return false;
    }
  };

  this.parse_standard_gps_data = function (str, msg_parts) {
    // Parse date: 6 bytes (12 hex chars) - YYMMDDHHMMSS
    const dateHex = str.substr(0, 12);
    const year = parseInt(dateHex.substr(0, 2), 16) + 2000;
    const month = parseInt(dateHex.substr(2, 2), 16);
    const day = parseInt(dateHex.substr(4, 2), 16);
    const hour = parseInt(dateHex.substr(6, 2), 16);
    const minute = parseInt(dateHex.substr(8, 2), 16);
    const second = parseInt(dateHex.substr(10, 2), 16);
    const date = new Date(year, month - 1, day, hour, minute, second);
    
    // Parse satellites (1 byte)
    const satellites = parseInt(str.substr(12, 2), 16);
    
    // Parse latitude (4 bytes = 8 hex chars)
    const latHex = str.substr(14, 8);
    let latitude = 0;
    if (latHex !== '00000000') {
      latitude = parseInt(latHex, 16) / 1800000;
    }
    
    // Parse longitude (4 bytes = 8 hex chars)
    const lngHex = str.substr(22, 8);
    let longitude = 0;
    if (lngHex !== '00000000') {
      longitude = parseInt(lngHex, 16) / 1800000;
    }
    
    // Parse speed (1 byte)
    const speed = parseInt(str.substr(30, 2), 16);
    
    // Parse course/heading (2 bytes = 4 hex chars)
    const courseHex = str.substr(32, 4);
    let course = parseInt(courseHex, 16);
    
    // Fix course
    if (course > 360) {
      course = course & 0xFF;
      course = (course * 360) / 255;
    }
    course = Math.round(course);
    
    const data = {
      device_id: msg_parts.device_id || '',
      date: date.toISOString(),
      timestampDate: date,
      latitude: latitude,
      longitude: longitude,
      speed: speed,
      orientation: course,
      satellites: satellites,
      raw_data: str
    };
    
    console.log('Parsed location:', {
      device: data.device_id,
      lat: data.latitude,
      lng: data.longitude,
      speed: data.speed,
      course: data.orientation,
      time: data.date
    });
    
    return data;
  };

  this.parse_compact_gps_data = function (str, msg_parts) {
    const date = new Date();
    
    let latitude = 0;
    let longitude = 0;
    let speed = 0;
    
    if (str.length >= 20) {
      try {
        const latPart = str.substr(0, 8);
        const lngPart = str.substr(8, 8);
        
        if (latPart !== '00000000' && lngPart !== '00000000') {
          latitude = parseInt(latPart, 16) / 1800000;
          longitude = parseInt(lngPart, 16) / 1800000;
        }
        
        if (str.length >= 22) {
          speed = parseInt(str.substr(16, 2), 16);
        }
      } catch (e) {
        console.error('Error parsing compact GPS:', e);
      }
    }
    
    return {
      device_id: msg_parts.device_id || '',
      date: date.toISOString(),
      timestampDate: date,
      latitude: latitude,
      longitude: longitude,
      speed: speed,
      orientation: 0,
      satellites: 0,
      raw_data: str
    };
  };

  // Alarm parsing (simplified)
  this.receive_alarm = function (msg_parts) {
    try {
      const deviceId = msg_parts.device_id || this.device.getUID ? this.device.getUID() : null;
      
      // Create simple alarm data
      const alarmData = {
        code: '01',
        msg: 'Alarm',
        device_id: deviceId,
        date: new Date().toISOString(),
        timestampDate: new Date(),
        alarm_type: 'Unknown Alarm',
        alarm_code: '01',
        raw_data: msg_parts.raw,
        protocol_id: msg_parts.protocol_id
      };
      
      console.log(`Alarm from ${deviceId}`);
      return alarmData;
    } catch (error) {
      console.error('Error parsing alarm:', error);
      return false;
    }
  };
};

exports.adapter = adapter;